'use strict';

// ─── avatar.js ──────────────────────────────────────────────────────────────
// Shared merchant avatar. Loaded globally (pages/partials/scripts.html) so
// every consumer — transactions.js, recurring.js — renders the SAME merchant
// the SAME way everywhere in the app.
//
// Two tiers, precision-first like the rest of the merchant matching:
//   1. A BUNDLED BRAND ICON, when the label matches a merchant with a shipped
//      icon (merchant-icons.js, generated by electron/scripts/fetch-merchant-
//      icons.js). Exact slug match only — see merchantIconSlug.
//   2. Otherwise the deterministic colour + initials circle, hashed from the
//      label, which needs no lookup table to stay stable.
//
// Icons are ordinary bundled assets under static/merchant-icons/, downloaded
// once on a developer's machine and committed. The app makes no network call and
// runs offline (see PRODUCT.md); nothing here fetches a logo at runtime, and a
// missing file falls back to tier 2 rather than showing a broken image. CSS for
// both tiers lives in ui.css.
//
// Extracted from transactions.js, which originated this algorithm for the
// ledger's row icon.

(function () {
    // Fast, deterministic string hash (djb2) — no cryptographic properties
    // needed, just a stable, well-distributed bucket per merchant name.
    function avatarHashString(str) {
        let h = 5381;
        for (let i = 0; i < str.length; i++) {
            h = ((h << 5) + h) + str.charCodeAt(i);
            h |= 0;
        }
        return Math.abs(h);
    }

    // First letters of the first two words, or the first two characters of a
    // single word. Leading punctuation is stripped per word first — raw bank
    // strings the lexicon did not clean up often start a word with '*' or '#'
    // (POS prefixes like "SQ *MERCHANT"), which would otherwise become the
    // initial. '?' covers the no-description case (never hashed to a colour —
    // see merchantAvatarHtml).
    function avatarInitials(name) {
        const words = String(name || '').trim().split(/\s+/)
            .map(w => w.replace(/^[^a-zA-Z0-9]+/, ''))
            .filter(Boolean);
        if (words.length === 0) return '?';
        if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
        return (words[0][0] + words[1][0]).toUpperCase();
    }

    // Trimmed copy of the noise patterns the backend categorizer strips before
    // matching (electron/backend/services/merchantCategories.js NOISE_PATTERNS)
    // — this file cannot require() that Node module (the renderer runs with
    // nodeIntegration off), and colour grouping only needs the *row-varying*
    // noise removed, not lexicon-grade precision, so this is a smaller subset:
    // payment-processor '*' prefixes, card masks, and
    // store/phone/trace/confirmation numbers. Without this, two deposits from
    // the same payroll processor ("DIRECT DEP ACME CORP ID:41355400" vs
    // "...ID:64140689") hashed as different merchants purely because their
    // trailing reference number differs — the same bug class the categorizer
    // solves for matching, just for colour instead of a category.
    const AVATAR_NOISE = [
        /\b(sq|tst|sp|pp|paypal|google|goog|apl|apple|toast|clover|venmo|cash app|zelle)\s*\*+\s*/gi,
        /[x*]{2,}\d+/gi,
        /\*+/g,
        /#\s*\d+/g,
        /\b\d{3}[-.\s]?\d{3}[-.\s]?\d{4}\b/g, // phone numbers
        /\b\d{1,2}\/\d{1,2}(?:\/\d{2,4})?\b/g, // embedded dates
        /\b\d{3,}\b/g, // standalone id/auth/store-number runs
    ];

    function avatarColorKey(label) {
        let s = String(label || '').toLowerCase();
        for (const re of AVATAR_NOISE) s = s.replace(re, ' ');
        return s.replace(/\s+/g, ' ').trim();
    }

    // 8 fixed slots (.avatar-circle-0..7 in ui.css) — light/desaturated steps
    // of the same 8 hues as the dataviz skill's categorical palette, evenly
    // spaced by hue angle for pastel distinguishability (see ui.css for why).
    // The colour hash runs on the noise-stripped key (above) so unmatched
    // merchants with a varying trailing reference number still land on one
    // colour; initials use the original label, since the first-two-words rule
    // rarely reaches that trailing noise and the label is what is printed
    // beside the circle.
    const AVATAR_SLOTS = 8;

    // ── Brand icons ─────────────────────────────────────────────────────────
    // The join between a label on screen and a file on disk. NOT the
    // noise-stripped colour key: that key is lossy by design (it groups
    // "ACME CORP ID:41355400" with "ACME CORP ID:64140689"), which is wrong when
    // the output is a specific brand's logo. This is an exact match on
    // alphanumerics — the label either equals the merchant's name or it does
    // not.
    //
    // In practice the label is already a curated display name for rows that can
    // match: the import pipeline writes transactions.display_name only from the
    // merchant lexicon's dictionary (see the clean-display-name rule), and that
    // same lexicon generated the icon set. A raw bank description that never
    // matched ("SQ *BLUE BOTTLE 866-123 CA") slugs to a string no brand uses and
    // falls through to the initials circle. Must stay identical to slugify() in
    // electron/scripts/fetch-merchant-icons.js.
    function merchantIconSlug(label) {
        return String(label || '')
            .toLowerCase()
            .replace(/&/g, 'and')
            .replace(/[^a-z0-9]+/g, '');
    }

    function merchantIconFile(label) {
        const map = window.MERCHANT_ICONS;
        if (!map) return null; // manifest not generated / not loaded
        const slug = merchantIconSlug(label);
        return (slug && Object.prototype.hasOwnProperty.call(map, slug)) ? map[slug] : null;
    }

    // Icons whose artwork reaches all four corners (a brand-colour tile, not a
    // mark on transparency) fill the circle and are clipped round. Everything
    // else is inset on a neutral disc, so a dark monogram drawn for a browser
    // tab has a background behind it. The measurement is done at build time from
    // the pixels (see merchant-icons.js); the browser cannot read an <img>'s
    // corner transparency. Built on first use so a page that renders no avatar
    // does no work.
    let bleedSet = null;
    function isFullBleed(file) {
        if (bleedSet === null) bleedSet = new Set(window.MERCHANT_ICONS_BLEED || []);
        return bleedSet.has(file);
    }

    // ── The setting (Settings → Appearance → Merchant Icons) ────────────────
    // Tier 1 is opt-OUT: on by default, and turning it off falls every avatar
    // back to tier 2, the same result as a merchant with no shipped icon.
    // localStorage-backed like the other display prefs (see settings.js); read
    // per render rather than cached at load, so rows drawn later use the current
    // setting.
    const ICONS_PREF_KEY = 'merchant_icons';

    function merchantIconsEnabled() {
        // Guarded: merchantIcons.test.js runs this file in a bare vm sandbox
        // with no localStorage, where the default (on) applies.
        if (typeof localStorage === 'undefined') return true;
        return localStorage.getItem(ICONS_PREF_KEY) !== '0';
    }

    function iconMarkup(file, initials, slot) {
        const fit = isFullBleed(file) ? ' avatar-circle-bleed' : '';
        // The initials circle this icon replaced is carried along on the
        // element, so the error path below can restore the real fallback
        // instead of an empty disc. Computing it here costs nothing and is
        // the only place the label is still in hand.
        return `<span class="avatar-circle avatar-circle-icon${fit}" aria-hidden="true"` +
            ` data-icon="${escapeHtml(file)}" data-fallback="${escapeHtml(initials)}" data-slot="${slot}">` +
            `<img src="/static/merchant-icons/${encodeURIComponent(file)}.png" alt="" loading="lazy"></span>`;
    }

    // `file` is the icon this merchant WOULD have shown, when there is one and
    // the setting is off. Keeping its name on the element is what lets the
    // toggle put the icon back in place (refreshMerchantAvatars) instead of
    // making every page re-render its rows.
    function initialsMarkup(initials, slot, file) {
        const carried = file
            ? ` data-icon="${escapeHtml(file)}" data-fallback="${escapeHtml(initials)}" data-slot="${slot}"`
            : '';
        return `<span class="avatar-circle avatar-circle-${slot}" aria-hidden="true"${carried}>${escapeHtml(initials)}</span>`;
    }

    /** The merchant avatar for `label`: a bundled brand icon when one exists and
     *  the setting is on, otherwise the deterministic colour + initials circle.
     *  `label` must already be escaped (callers pass it through escapeHtml
     *  themselves, as every other HTML-string renderer in this app does). */
    function merchantAvatarHtml(label) {
        const initials = avatarInitials(label);
        const colorKey = avatarColorKey(label);
        const slot = colorKey ? avatarHashString(colorKey) % AVATAR_SLOTS : 0;

        const file = merchantIconFile(label);
        return (file && merchantIconsEnabled())
            ? iconMarkup(file, initials, slot)
            : initialsMarkup(initials, slot, file);
    }

    // ── Swapping tiers in place ─────────────────────────────────────────────
    // Both directions, on an avatar already in the DOM, using the data
    // attributes the markup above always carries. No page references the
    // setting.

    function showInitials(box) {
        box.classList.remove('avatar-circle-icon', 'avatar-circle-bleed');
        box.classList.add(`avatar-circle-${box.dataset.slot || 0}`);
        box.textContent = box.dataset.fallback || '?';
    }

    function showIcon(box) {
        const file = box.dataset.icon;
        if (!file) return;
        box.classList.remove(`avatar-circle-${box.dataset.slot || 0}`);
        box.classList.add('avatar-circle-icon');
        box.classList.toggle('avatar-circle-bleed', isFullBleed(file));
        box.textContent = '';
        const img = document.createElement('img');
        img.alt = '';
        img.loading = 'lazy';
        img.src = `/static/merchant-icons/${encodeURIComponent(file)}.png`;
        box.appendChild(img);
    }

    /** Bring every avatar already on the page in line with the current setting.
     *  Called by settings.js when the toggle flips, so the change lands on the
     *  open page without a reload and without any page re-fetching its rows.
     *  Only avatars with an icon to show or hide carry [data-icon]. */
    function refreshMerchantAvatars(root) {
        const on = merchantIconsEnabled();
        (root || document).querySelectorAll('.avatar-circle[data-icon]').forEach(box => {
            if (box.classList.contains('avatar-circle-icon') === on) return;
            if (on) showIcon(box);
            else showInitials(box);
        });
    }

    // A brand icon that fails to load (file pruned, asset dir missing from a
    // package) would otherwise leave a broken-image glyph in the ledger. Swap
    // it for the initials circle it would have been — same size, same colour it
    // would have hashed to, so the row is indistinguishable from one whose
    // merchant we never had an icon for. The icon's name goes with it: a file
    // that just failed shouldn't come back on the next toggle. Capture-phase,
    // because <img> error events do not bubble; one listener on the document
    // covers every avatar any page renders, including the ones drawn later.
    document.addEventListener('error', (ev) => {
        const img = ev.target;
        const box = img && img.tagName === 'IMG' ? img.parentElement : null;
        if (!box || !box.classList.contains('avatar-circle-icon')) return;
        showInitials(box);
        delete box.dataset.icon;
    }, true);

    window.merchantAvatarHtml = merchantAvatarHtml;
    window.merchantIconSlug = merchantIconSlug;
    window.merchantIconsEnabled = merchantIconsEnabled;
    window.refreshMerchantAvatars = refreshMerchantAvatars;
}());
